import re
from datetime import datetime, timezone

RETRYABLE_STATUSES = {429, 502, 503, 504}
IDEMPOTENT_METHODS = {"GET", "HEAD", "OPTIONS", "PUT", "DELETE"}
UNSAFE_METHODS = {"POST", "PATCH"}
DEFAULT_PROFILE = (5, 8.0, 30.0)
PROFILES = {
    "catalog": (6, 8.0, 30.0),
    "ledger": (8, 3.0, 60.0),
    "payments": (3, 1.0, 30.0),
    "reports": (9, 5.0, 120.0),
    "inventory": (7, 4.0, 90.0),
    "search": (10, 12.0, 45.0),
    "shipping": (8, 3.0, 40.0),
    "auth": (6, 6.0, 20.0),
    "ledger-export": (4, 8.0, 10.0),
    "media": (5, 8.0, 15.0),
}
MONTHS = {
    name: index
    for index, name in enumerate(
        ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"], 1
    )
}
HTTP_DATE = re.compile(
    r"(?:Mon|Tue|Wed|Thu|Fri|Sat|Sun), (\d{2}) ([A-Z][a-z]{2}) (\d{4}) "
    r"(\d{2}):(\d{2}):(\d{2}) GMT"
)


def _header(headers, name):
    for key, value in (headers or {}).items():
        if key.lower() == name:
            return value
    return None


def _retry_after_seconds(value, now):
    if value is None:
        return None
    value = value.strip()
    if value.isascii() and value.isdigit():
        return float(int(value))
    match = HTTP_DATE.fullmatch(value)
    if not match or match.group(2) not in MONTHS:
        return None
    day, _, year, hour, minute, second = match.groups()
    try:
        when = datetime(
            int(year), MONTHS[match.group(2)], int(day),
            int(hour), int(minute), int(second), tzinfo=timezone.utc,
        )
    except ValueError:
        return None
    return max(0.0, (when - now).total_seconds())


EOF
python - <<'EOF'
src=open('shipclient/retry.py').read()
new=open('/tmp/new.py').read()
src=src.replace("from datetime import datetime\n\n\n",new,1) if False else src
head,rest=src.split("from datetime import datetime\n\n\n")
rest=rest.replace("    raise NotImplementedError\n",'''    if status is not None and status not in RETRYABLE_STATUSES:
        return None
    verb = method.upper()
    if verb in UNSAFE_METHODS:
        key = _header(request_headers, "idempotency-key")
        if key is None or not key.strip():
            return None
    elif verb not in IDEMPOTENT_METHODS:
        return None

    service = _header(request_headers, "x-service")
    limit, cap, longest = PROFILES.get(
        service.strip().lower() if service else "", DEFAULT_PROFILE
    )
    if attempt >= limit:
        return None

    delay = min(0.25 * 2 ** (attempt - 1), cap)
    if status in (429, 503):
        wait = _retry_after_seconds(_header(response_headers, "retry-after"), now)
        if wait is not None:
            if wait > longest:
                return None
            delay = max(delay, wait)
    return delay
''')
open('shipclient/retry.py','w').write(head+new+"\n"+rest)
EOF
sed -i 's/^\n\n\n\ndef/\n\n\ndef/' shipclient/retry.py
echo '{"status":"success","summary":"Implemented retry_delay per HTTP client standard v3, idempotency rules, rate-limit handling and the current per-service retry profiles (ignoring drafts/superseded/withdrawn)."}' > STATUS.json
python -m unittest 2>&1 | tail -3

